'use strict';

// MODULES //

var offset = require( '@stdlib/ndarray-base-offset' );


// MAIN //

/**
* Returns the index offset specifying the underlying buffer index of the first iterated element for each ndarray in a provided list of ndarrays.
*
* @param {ArrayLikeObject<ndarrayLike>} arr - list of ndarray-like objects
* @returns {Array<integer>} list of offsets
*
* @example
* var zeros = require( '@stdlib/ndarray-zeros' );
*
* var x = zeros( [ 3, 3, 3 ] );
*
* var out = offsets( [ x ] );
* // returns [ 0 ]
*/
function offsets( arr ) {
	var out = [];
	var i;
	for ( i = 0; i < arr.length; i++ ) {
		out.push( offset( arr[ i ] ) );
	}
	return out;
}


// EXPORTS //

module.exports = offsets;
